"""Persisted, cross-domain recommendations generated by Analytics."""

import json
import hashlib
from datetime import datetime, timedelta, timezone
import sqlparse
from sqlparse.tokens import Literal, Name, Comment
from dataclasses import dataclass
from typing import Any

from sqlalchemy import text
from sqlalchemy.ext.asyncio import AsyncSession


from analytics.services.index_advisor import coverage, index_shape, predicate_roles, quote, IndexShape
from analytics.services.index_workload import table_evidence, query_evidence, WINDOW_DAYS


@dataclass(frozen=True)
class RecommendationDraft:
    """A recommendation with its supporting evidence."""

    fingerprint: str
    category: str
    severity: str
    confidence: float
    title: str
    summary: str
    recommendation: str
    evidence: dict[str, Any]


async def refresh_recommendations(session: AsyncSession, database_id: int) -> int:
    """Generate and upsert the currently supported database recommendations."""
    drafts = await _find_table_maintenance(session, database_id)
    tables = await table_evidence(session, database_id)
    drafts.extend(await _find_unused_indexes(session, database_id, tables))
    drafts.extend(await _find_missing_indexes(session, database_id, tables))
    capacity = await _find_capacity_fit(session, database_id)
    if capacity is not None:
        drafts.append(capacity)
    for draft in drafts:
        await _upsert(session, database_id, draft)
    # Retire stale index suggestions after metadata/workload changes, including
    # legacy fingerprints. Preserve explicit dismissals.
    await session.execute(text("""
        UPDATE analytics.recommendation SET status = 'resolved'
        WHERE database_id = :database_id AND category = 'index' AND status = 'open'
          AND NOT (fingerprint = ANY(CAST(:active AS text[])))
    """), {"database_id": database_id, "active": [d.fingerprint for d in drafts if d.category == "index"]})
    return len(drafts)


async def _find_table_maintenance(session: AsyncSession, database_id: int) -> list[RecommendationDraft]:
    result = await session.execute(text("""
        SELECT table_id, schema_name, name, n_live_tup, n_dead_tup, last_vacuum, last_autovacuum
        FROM (
            SELECT DISTINCT ON (t.id) t.id AS table_id, t.schema_name, t.name,
                   m.n_live_tup, m.n_dead_tup, m.last_vacuum, m.last_autovacuum
            FROM metadata.table t JOIN metric.table m ON m.table_id = t.id
            WHERE t.database_id = :database_id AND t.deleted_at IS NULL
            ORDER BY t.id, m.collected_at DESC
        ) latest
        WHERE n_dead_tup >= 10000 AND n_dead_tup::float / GREATEST(n_live_tup, 1) >= 0.20
    """), {"database_id": database_id})
    return [
        RecommendationDraft(
            fingerprint=f"vacuum:{row.table_id}", category="maintenance", severity="warning",
            confidence=0.78, title=f"Vacuum may be needed for {row.schema_name}.{row.name}",
            summary="Dead tuples exceed 20% of live tuples, which can increase scan cost.",
            recommendation="Review autovacuum and consider VACUUM (ANALYZE) outside peak traffic.",
            evidence={"table_id": row.table_id, "table": f"{row.schema_name}.{row.name}",
                      "live_tuples": row.n_live_tup, "dead_tuples": row.n_dead_tup,
                      "dead_tuple_ratio": round(row.n_dead_tup / max(row.n_live_tup or 0, 1), 4),
                      "last_vacuum": _iso(row.last_vacuum), "last_autovacuum": _iso(row.last_autovacuum)},
        ) for row in result.mappings()
    ]


async def _find_unused_indexes(session: AsyncSession, database_id: int, tables: dict | None = None) -> list[RecommendationDraft]:
    tables = tables if tables is not None else await table_evidence(session, database_id)
    result = await session.execute(text("""
        SELECT i.id AS index_id, t.id AS table_id, t.schema_name, t.name AS table_name,
               i.name AS index_name, latest.size, latest.scan_qt,
               EXTRACT(EPOCH FROM latest.collected_at - observed.first_at) AS observation_seconds
        FROM metadata.index i JOIN metadata.table t ON t.id = i.table_id
        JOIN LATERAL (
            SELECT size, scan_qt, collected_at FROM metric.index
            WHERE index_id = i.id ORDER BY collected_at DESC LIMIT 1
        ) latest ON TRUE
        JOIN LATERAL (
            SELECT MIN(collected_at) AS first_at, MAX(scan_qt) AS max_scans,
                   COUNT(scan_qt) AS samples
            FROM metric.index WHERE index_id = i.id
              AND collected_at >= NOW() - INTERVAL '30 days'
        ) observed ON TRUE
        WHERE i.database_id = :database_id AND i.deleted_at IS NULL AND t.deleted_at IS NULL
          AND NOT i.is_primary AND NOT i.is_unique
          AND latest.size >= 67108864 AND latest.scan_qt = 0
          AND observed.max_scans = 0 AND observed.samples >= 2
          AND latest.collected_at >= NOW() - INTERVAL '1 day'
          AND latest.collected_at - observed.first_at >= INTERVAL '7 days'
    """), {"database_id": database_id})
    drafts = []
    for row in result.mappings():
        costs = tables.get(row.table_id, {})
        drafts.append(RecommendationDraft(
            fingerprint=f"unused-index:{row.index_id}", category="index", severity="info",
            confidence=0.55, title=f"Review unused index {row.index_name}",
            summary="This non-unique index is at least 64 MB and has no recorded scans over the observed period.",
            recommendation="Review workload, statistics resets, replicas and constraint dependencies before considering removal.",
            evidence={"index_id": row.index_id, "table": f"{row.schema_name}.{row.table_name}",
                      "index": row.index_name, "size_bytes": row.size, "scan_count": row.scan_qt,
                      "observation_seconds": float(row.observation_seconds), **costs},
        ))
    return drafts


def _template(sql: str) -> str:
    return " ".join("?" if token.ttype in Literal or token.ttype in Name.Placeholder else token.normalized
                    for statement in sqlparse.parse(sql) for token in statement.flatten()
                    if not token.is_whitespace and token.ttype not in Comment)


async def _find_missing_indexes(session: AsyncSession, database_id: int, tables: dict | None = None) -> list[RecommendationDraft]:
    tables = tables if tables is not None else await table_evidence(session, database_id)
    workload = await query_evidence(session, database_id)
    indexes_result = await session.execute(text("""
        SELECT i.table_id, i.name, i.definition, i.type, i.is_valid
        FROM metadata.index i WHERE i.database_id = :database_id AND i.deleted_at IS NULL
    """), {"database_id": database_id})
    indexes = {}
    for row in indexes_result.mappings():
        shape = index_shape(row.name, row.definition, row.type)
        if row.is_valid is not True:
            shape = IndexShape(shape.name, shape.keys, False)
        indexes.setdefault(row.table_id, []).append(shape)
    # Recompute candidates from column hits and current metadata, rather than
    # perpetuating old findings. Templates remove literal variants; active-query
    # samples are never counted as executions.
    result = await session.execute(text("""
        SELECT q.id AS query_id, q.query, t.id AS table_id,
            t.schema_name, t.name AS table_name,
            jsonb_build_object('advisor_version', 2,
                'missing_prefix_columns', jsonb_agg(DISTINCT hit.column_name)) AS evidence,
            COALESCE(q.pg_query_id, NULLIF(native.query_id, 0)) AS native_query_id
        FROM analytics.query q
        JOIN analytics.query_column_hit hit ON hit.query_id = q.id
            AND (hit.is_condition OR hit.is_condition_foreign)
        JOIN metadata.table t ON t.database_id = q.database_id
            AND t.schema_name = hit.schema_name AND t.name = hit.table_name
            AND t.deleted_at IS NULL
        LEFT JOIN LATERAL (
            SELECT query_id, collected_at FROM metric.native_query n
            WHERE n.database_id = q.database_id
              AND ((q.pg_query_id IS NOT NULL AND n.query_id = q.pg_query_id)
                   OR (q.pg_query_id IS NULL AND (n.query_hash = q.hash OR n.query = q.query)))
            ORDER BY n.collected_at DESC LIMIT 1
        ) native ON TRUE
        WHERE q.database_id = :database_id
          AND (q.created_at >= NOW() - make_interval(days => :days)
               OR native.collected_at >= NOW() - make_interval(days => :days)
               OR EXISTS (SELECT 1 FROM metric.query_workload w
                          WHERE w.database_id = q.database_id AND w.query_id = COALESCE(q.pg_query_id, native.query_id)
                            AND w.collected_at >= NOW() - make_interval(days => :days)))
        GROUP BY q.id, q.query, t.id, t.schema_name, t.name, native.query_id
    """), {"database_id": database_id, "days": WINDOW_DAYS})
    groups = {}
    for row in result.mappings():
        evidence = row.evidence if isinstance(row.evidence, dict) else json.loads(row.evidence)
        columns = evidence.get("missing_prefix_columns", [])
        if not columns or not all(isinstance(c, str) for c in columns):
            continue
        # Re-check against CURRENT metadata, including old findings. Old findings
        # did not preserve the full predicate, so they can only request review.
        equality, ranges, understood = predicate_roles(row.query, set(columns))
        if evidence.get("advisor_version") != 2:
            understood = False
        shapes = indexes.get(row.table_id, [])
        state, matching = coverage(shapes, equality, ranges, understood)
        if state == "covered":
            continue
        ordered = tuple(sorted(set(columns), key=lambda c: (c not in equality, c)))
        key = (row.table_id, ordered, state)
        group = groups.setdefault(key, {"row": row, "patterns": set(), "ids": set(), "matching": set(), "unmapped": False,
                                        "ranges": ranges, "equality": equality})
        group["ranges"].update(ranges)
        group["equality"].intersection_update(equality)
        group["patterns"].add(_template(row.query))
        if row.native_query_id is not None:
            group["ids"].add(row.native_query_id)
        else:
            group["unmapped"] = True
        group["matching"].update(matching)
    total_time = sum(float(w["total_exec_time_ms"] or 0) for w in workload.values())
    drafts = []
    for (table_id, columns, state), group in groups.items():
        row = group["row"]
        costs = tables.get(table_id, {})
        stats = [workload[qid] for qid in group["ids"] if qid in workload]
        calls = sum(int(w["calls"] or 0) for w in stats)
        time_ms = sum(float(w["total_exec_time_ms"] or 0) for w in stats)
        share = time_ms / total_time if total_time else None
        sufficient = bool(stats) and all(
            (w["last_seen_at"] - w["first_seen_at"]).total_seconds() >= 3600
            and w["last_seen_at"] >= datetime.now(timezone.utc) - timedelta(days=1) for w in stats)
        complete = sufficient and not group["unmapped"] and len(stats) == len(group["ids"]) and len(group["ids"]) > 0
        measured_impact = complete and calls >= 100 and time_ms >= 60_000 and (share or 0) >= 0.05
        # Warning expresses measured workload relevance, never a proven speedup.
        severity = "warning" if measured_impact and state == "missing" and costs.get("write_heavy") is False else "info"
        confidence = 0.65 if complete and costs.get("writes_per_second") is not None else 0.45
        if state != "missing" or costs.get("write_heavy"):
            confidence = min(confidence, 0.4)
        table_name = f"{row.schema_name}.{row.table_name}"
        ddl = None
        if state == "missing" and len(group["ranges"]) <= 1:
            ddl = f"CREATE INDEX CONCURRENTLY ON {quote(row.schema_name)}.{quote(row.table_name)} ({', '.join(quote(c) for c in columns)});"
        action = "validate_candidate" if ddl else "review_existing_indexes"
        matching = sorted(group["matching"])
        summary = f"Filter coverage is {state} across {len(group['patterns'])} query pattern(s). "
        if stats:
            summary += f"Associated workload used {time_ms / 1000:.1f}s across {calls:,} calls in the observed window. "
        if costs.get("write_heavy"):
            summary += "High write activity requires stronger evidence before adding an index. "
        if not complete:
            summary += "Workload evidence is incomplete; priority is limited."
        recommendation = (f"Candidate for validation: {ddl} " if ddl else "Review the existing indexes and query plan. ")
        recommendation += "Compare execution plans and write/storage impact before applying changes."
        if matching:
            recommendation += " Evaluate consolidation with " + ", ".join(matching) + "; do not assume replacement is safe."
        fingerprint_key = json.dumps([table_id, columns, state], ensure_ascii=False)
        drafts.append(RecommendationDraft(
            fingerprint="missing-index:v2:" + hashlib.sha256(fingerprint_key.encode()).hexdigest()[:24],
            category="index", severity=severity, confidence=confidence,
            title=f"Review index coverage on {table_name}", summary=summary.strip(), recommendation=recommendation,
            evidence={"table": table_name, "table_id": table_id, "missing_columns": list(columns),
                      "query_count": len(group["patterns"]), "coverage": state, "action": action,
                      "matching_indexes": matching, "suggested_ddl": ddl, "window_days": WINDOW_DAYS,
                      "equality_columns": sorted(group["equality"]), "range_columns": sorted(group["ranges"]),
                      "overlapping_indexes": sorted(shape.name for shape in indexes.get(table_id, [])
                                                    if set(shape.keys) & set(columns)),
                      "calls": calls if stats else None, "total_exec_time_ms": time_ms if stats else None,
                      "workload_time_share": round(share, 4) if share is not None else None,
                      "shared_blks_read": sum(int(w["shared_blks_read"] or 0) for w in stats) if stats else None,
                      "shared_blks_hit": sum(int(w["shared_blks_hit"] or 0) for w in stats) if stats else None,
                      "mean_exec_time_ms": round(time_ms / calls, 2) if calls else None,
                      "workload_evidence_complete": complete, "requires_plan_validation": True,
                      "benefit_estimate": None, **costs},
        ))
    # Compare candidates for the same table. A candidate that may serve another
    # pattern is an alternative to validate, not permission to replace an index.
    compared = []
    for draft in drafts:
        alternatives = []
        for other in drafts:
            if other is draft or other.evidence["table_id"] != draft.evidence["table_id"] or not other.evidence["suggested_ddl"]:
                continue
            shape = IndexShape(other.fingerprint, tuple(other.evidence["missing_columns"]), True)
            state, _ = coverage([shape], set(draft.evidence["equality_columns"]),
                                set(draft.evidence["range_columns"]), draft.evidence["coverage"] != "uncertain")
            if state == "covered":
                alternatives.append(other.fingerprint)
        draft.evidence["alternative_candidate_fingerprints"] = sorted(alternatives)
        if alternatives:
            draft.evidence["action"] = "compare_shared_candidates"
            draft = RecommendationDraft(**{**draft.__dict__, "recommendation": draft.recommendation
                + " Compare the shared candidate indexes listed in the evidence before choosing which to create."})
        compared.append(draft)
    return sorted(compared, key=lambda d: (d.severity == "warning", d.evidence.get("total_exec_time_ms") or 0), reverse=True)


async def _find_capacity_fit(session: AsyncSession, database_id: int) -> RecommendationDraft | None:
    result = await session.execute(text("""
        SELECT AVG(cpu.cpu_percent) AS avg_cpu, MAX(cpu.cpu_percent) AS max_cpu, COUNT(cpu.cpu_percent) AS cpu_samples,
               AVG(ram.percent) AS avg_ram, MAX(ram.percent) AS max_ram, COUNT(ram.percent) AS ram_samples
        FROM metadata.database db
        LEFT JOIN metric.cpu cpu ON cpu.server_id = db.server_id AND cpu.collected_at >= NOW() - INTERVAL '30 days'
        LEFT JOIN metric.ram ram ON ram.server_id = db.server_id AND ram.collected_at >= NOW() - INTERVAL '30 days'
        WHERE db.id = :database_id
        GROUP BY db.id
    """), {"database_id": database_id})
    row = result.mappings().one_or_none()
    if not row or min(row.cpu_samples or 0, row.ram_samples or 0) < 24:
        return None
    if any(value is None for value in (row.avg_cpu, row.max_cpu, row.avg_ram, row.max_ram)):
        return None
    if row.avg_cpu >= 20 or row.max_cpu >= 45 or row.avg_ram >= 55 or row.max_ram >= 75:
        return None
    return RecommendationDraft(
        fingerprint="capacity-fit:overprovisioned", category="capacity", severity="info", confidence=0.7,
        title="Server may be overprovisioned", summary="CPU and memory remained below conservative thresholds over 30 days.",
        recommendation="Confirm peak and seasonal workload before reducing server resources.",
        evidence={"period_days": 30, "cpu_avg_percent": round(row.avg_cpu, 2), "cpu_max_percent": round(row.max_cpu, 2),
                  "ram_avg_percent": round(row.avg_ram, 2), "ram_max_percent": round(row.max_ram, 2),
                  "cpu_samples": row.cpu_samples, "ram_samples": row.ram_samples},
    )


async def _upsert(session: AsyncSession, database_id: int, draft: RecommendationDraft) -> None:
    await session.execute(text("""
        INSERT INTO analytics.recommendation
            (database_id, fingerprint, category, severity, confidence, title, summary, recommendation, evidence)
        VALUES (:database_id, :fingerprint, :category, :severity, :confidence, :title, :summary,
                :recommendation, CAST(:evidence AS jsonb))
        ON CONFLICT (database_id, fingerprint) DO UPDATE SET
            category = EXCLUDED.category, severity = EXCLUDED.severity, confidence = EXCLUDED.confidence,
            title = EXCLUDED.title, summary = EXCLUDED.summary, recommendation = EXCLUDED.recommendation,
            evidence = EXCLUDED.evidence, last_seen_at = NOW(),
            status = CASE WHEN analytics.recommendation.status = 'dismissed' THEN 'dismissed' ELSE 'open' END
    """), {"database_id": database_id, **draft.__dict__, "evidence": json.dumps(draft.evidence, default=str)})
    if draft.severity == "critical":
        await _notify_critical(session, database_id, draft)


async def _notify_critical(
    session: AsyncSession,
    database_id: int,
    draft: RecommendationDraft,
) -> None:
    await session.execute(text("""
        INSERT INTO notifier.notification (message, params)
        SELECT :message, jsonb_build_object(
            'path', '/analytics/' || database.public_id::text || '/recommendations',
            'source', 'analytics recommendations',
            'scope', 'database',
            'type', 'recommendation',
            'database_id', :database_id,
            'fingerprint', :fingerprint,
            'category', :category,
            'severity', 'critical'
        )
        FROM metadata.database AS database
        WHERE database.id = :database_id
          AND NOT EXISTS (
              SELECT 1
              FROM notifier.notification AS notification
              WHERE notification.params->>'source' = 'analytics recommendations'
                AND notification.params->>'database_id' = CAST(:database_id AS text)
                AND notification.params->>'fingerprint' = :fingerprint
          )
    """), {
        "message": f"Critical analytics recommendation: {draft.title}",
        "database_id": database_id,
        "fingerprint": draft.fingerprint,
        "category": draft.category,
    })


def _iso(value: Any) -> str | None:
    return value.isoformat() if value else None
